public final class Throwables
{
  public static boolean isThrowable(Throwable t, Class<? extends Throwable> searchFor)
  {
    if (t.getClass().isAssignableFrom(searchFor)) {
      return true;
    } else {
      if (t.getCause() != null) {
        return isThrowable(t.getCause(), searchFor);
      } else {
        return false;
      }
    }
  }

  private Throwables()
  {
  }
}

