                        firstVisit = (Date) propertyFirstVisit;
                    } else {
                        firstVisit = format.parse(propertyFirstVisit.toString());
                    }
                }

                if (event.getTimeStamp().after(firstVisit)) {
                    date = event.getTimeStamp();
                }
            } catch (ParseException e) {
