    if (it != params.end()) {
        flowPtr_ = FlowPtr(
            new ClientCredentialFlow(params["issuer_url"], params["private_key"], params["audience"]));
    } else {
        flowPtr_ = FlowPtr(new ClientCredentialFlow(params["issuer_url"], params["client_id"],
                                                    params["client_secret"], params["audience"]));
    }
}

