  public Replica getReplica(BiPredicate<String, Replica> predicate) {
    final Replica[] result = new Replica[1];
    forEachReplica(
        (s, replica) -> {
          if (result[0] != null) return;
          if (predicate.test(s, replica)) {
            result[0] = replica;
          }
        });
    return result[0];
  }

