        Set<String> liveNodes = applyStatusFilter ? cs.getLiveNodes() : null;

        collectionStates = new TreeMap<>(pagingSupport);
        for (String collection : page.selected) {
          DocCollection dc = cs.getCollectionOrNull(collection);
