    RequestHandlerUtils.setWt(req, JSON);
    final SolrRequest.METHOD httpMethod = (SolrRequest.METHOD) req.getContext().get("httpMethod");
    switch (httpMethod) {
      case POST:
        if (isImmutableConfigSet) {
